scenario.en:
@Injectable()
export class ReconcileJob {
  @Cron('0 3 * * *')
  handle() {
    void this.doReconcile(); // fire-and-forget — not awaited
  }
  async doReconcile() {
    const rows = await this.repo.find();
    for (const r of rows) this.apply(r); // throws on a malformed row
  }
}

The app boots with `app.useGlobalFilters(new SentryExceptionFilter())` and NO process.on handlers. The job runs at 03:00, doReconcile rejects. Does Sentry receive the error? What happens to the worker pod?

