// main.ts
Sentry.init({
  dsn: process.env.SENTRY_DSN,
  release: process.env.GIT_SHA,          // spike maps to a deploy SHA
  beforeSend(event) {                    // scrub BEFORE anything leaves the process
    const h = event.request?.headers;
    if (h) { delete h['authorization']; delete h['cookie']; }
    if (event.request?.data) event.request.data = redactSecrets(event.request.data);
    return event;
  },
});

// Cover out-of-band errors the global filter CANNOT see:
process.on('unhandledRejection', (reason) => Sentry.captureException(reason));
process.on('uncaughtException', (err) => {
  Sentry.captureException(err);
  Sentry.flush(2000).finally(() => process.exit(1)); // report, drain, then exit
});

const app = await NestFactory.create(AppModule);
app.useGlobalFilters(new SentryExceptionFilter()); // still covers the request pipeline
await app.listen(3000);

Why: the global filter only catches throws inside the request pipeline, so a background timer/job rejection needs process.on('unhandledRejection') / 'uncaughtException' to be reported instead of crash-looping silently. And because Sentry is a third party, beforeSend must deny-list the Authorization and Cookie headers and redact tokens, or you leak live credentials to your vendor — a breach. release ties any spike to a deploy.

