// main.ts
Sentry.init({
  dsn: process.env.SENTRY_DSN,
  release: process.env.GIT_SHA,          // всплеск маппится на SHA деплоя
  beforeSend(event) {                    // вычисти ДО того, как что-либо покинет процесс
    const h = event.request?.headers;
    if (h) { delete h['authorization']; delete h['cookie']; }
    if (event.request?.data) event.request.data = redactSecrets(event.request.data);
    return event;
  },
});

// Покрой out-of-band ошибки, которые глобальный filter НЕ видит:
process.on('unhandledRejection', (reason) => Sentry.captureException(reason));
process.on('uncaughtException', (err) => {
  Sentry.captureException(err);
  Sentry.flush(2000).finally(() => process.exit(1)); // зарепорти, слей, потом выйди
});

const app = await NestFactory.create(AppModule);
app.useGlobalFilters(new SentryExceptionFilter()); // всё ещё покрывает пайплайн запроса
await app.listen(3000);

Почему: глобальный filter ловит только throw'ы внутри пайплайна запроса, так что rejection из фонового таймера/джобы требует process.on('unhandledRejection') / 'uncaughtException', чтобы быть зарепорченным, а не тихо crash-loop'ить. И поскольку Sentry — третья сторона, beforeSend обязан deny-листить заголовки Authorization и Cookie и редактировать токены, иначе ты утечёшь живые креды вендору — breach. release привязывает любой всплеск к деплою.
